U=bench72968351
H=/home/$U
RT=/run/user/$(id -u $U)
as_user() { sudo -u $U -H env XDG_RUNTIME_DIR=$RT DBUS_SESSION_BUS_ADDRESS=unix:path=$RT/bus "$@"; }
as_user mkdir -p $H/bin
as_user tee $H/bin/ctr-k3s >/dev/null <<'SCRIPT'
#!/bin/sh
RT=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}
CP=$(cat "$RT/bench72968351-rootlesskit/child_pid")
export CONTAINERD_NAMESPACE=${CONTAINERD_NAMESPACE:-k8s.io}
exec nsenter -U --preserve-credentials -m -t "$CP" ctr --address /run/k3s/containerd/containerd.sock --timeout 10s "$@"
SCRIPT
as_user tee $H/bin/crictl-k3s >/dev/null <<'SCRIPT'
#!/bin/sh
RT=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}
CP=$(cat "$RT/bench72968351-rootlesskit/child_pid")
exec nsenter -U --preserve-credentials -m -t "$CP" crictl --timeout 10s --runtime-endpoint unix:///run/k3s/containerd/containerd.sock --image-endpoint unix:///run/k3s/containerd/containerd.sock "$@"
SCRIPT
as_user chmod +x $H/bin/ctr-k3s $H/bin/crictl-k3s
